package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;
final class DeliveryArchiveBrowserAcceptance {
 static void click(Page page,String name){ServiceOutagesBrowserAcceptance.click(page,name);}
 static void run(BrowserTest h)throws Exception{
  String held;try(var db=h.store.open()){db.update("DELETE FROM os_retention_hold");db.update("DELETE FROM os_delivery_archive");db.update("DELETE FROM os_outbox");db.update("UPDATE os_retention_policy SET days=90,revision=1");DeliveryArchiveAcceptance.seed(db,"delivered",1);held=DeliveryArchiveAcceptance.seed(db,"cancelled",2);db.connection.commit();}
  try(var p=Playwright.create();var browser=p.chromium().launch();var context=browser.newContext()){
   var page=context.newPage();h.login(page,"admin");page.navigate(h.base()+"/admin/delivery");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Review recoverable archives and retention holds")).press("Enter");page.getByLabel("Days after link expiry").fill("30");click(page,"Save retention policy");page.getByLabel("Delivery job ID").fill(held);page.getByLabel("Reason for hold").fill("Preserve <script>evidence</script>");click(page,"Place retention hold");assertThat(page.locator("main")).containsText("Preserve <script>evidence</script>");assertThat(page.locator("main script")).hasCount(0);click(page,"Review eligible metadata");assertThat(page.getByRole(AriaRole.HEADING,new Page.GetByRoleOptions().setName("Review exact archive batch"))).isVisible();assertThat(page.locator("main")).containsText("Records in this review: 1");ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/delivery-archive-review-light.png")).setFullPage(true));click(page,"Dark mode");page.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(page);assertEquals(false,page.evaluate("document.documentElement.scrollWidth>window.innerWidth"));assertEquals(true,page.evaluate("Array.from(document.querySelectorAll('main .panel')).every(e=>e.scrollWidth<=e.clientWidth)"));page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/delivery-archive-review-dark.png")).setFullPage(true));page.getByLabel("Confirm this exact metadata operation").check();click(page,"Archive reviewed metadata");assertThat(page.locator("[role=status]")).containsText("1 metadata records · archived");assertThat(page.locator("main")).not().containsText("No archive batches.");click(page,"Review restoration");assertThat(page.getByRole(AriaRole.HEADING,new Page.GetByRoleOptions().setName("Review metadata restoration"))).isVisible();page.getByLabel("Confirm this exact metadata operation").check();click(page,"Restore reviewed metadata");assertThat(page.locator("[role=status]")).containsText("1 metadata records · restored");ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/delivery-archive-restored-dark.png")).setFullPage(true));click(page,"View restored receipt");assertThat(page.locator("[role=status]")).containsText("restored");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Release hold "+held).setExact(true)).press("Enter");assertThat(page.locator("main")).containsText("No active holds.");try(var db=h.store.open()){assertEquals(2,db.count("SELECT COUNT(*) FROM os_outbox"));assertNull(Outbox.claim(db,System.currentTimeMillis()));}
  }
 }
}
